export const getColissimoCost = (weightInGrams: number): number => {
    if (weightInGrams <= 0) return 0;
    if (weightInGrams <= 500) return 7.10;   // 1 flacon (450g)
    if (weightInGrams <= 1000) return 9.59;  // 2 flacons (900g)
    return 0;                                // Dès 3 flacons (>= 1350g) : GRATUIT
};

export const getMondialRelayCost = (weightInGrams: number): number => {
    // Grille tarifaire Mondial Relay France 2026
    if (weightInGrams <= 0) return 0;
    if (weightInGrams <= 250) return 4.10;
    if (weightInGrams <= 500) return 4.10;
    if (weightInGrams <= 750) return 5.10;
    if (weightInGrams <= 1000) return 5.10;
    if (weightInGrams <= 2000) return 6.60;
    if (weightInGrams <= 4000) return 7.99;
    if (weightInGrams <= 5000) return 15.99;
    if (weightInGrams <= 7000) return 15.99;
    if (weightInGrams <= 10000) return 15.99;
    return 15.99; // Fallback for weights over 10kg
};

// International Mondial Relay rates for BE, NL, DE, LU
export const getMondialRelayInternationalCost = (countryCode: string, weightInGrams: number): number => {
    const rates: Record<string, Record<number, number>> = {
        'FR': { // France
            250: 4.05, 500: 4.05, 750: 4.05, 1000: 5.00, 2000: 6.00,
            4000: 7.00, 5000: 8.00, 7000: 9.50, 10000: 12.00
        },
        'BE': { // Belgique
            250: 5.50, 500: 5.50, 750: 6.50, 1000: 6.50, 2000: 8.00,
            4000: 9.50, 5000: 18.50, 7000: 18.50, 10000: 18.50
        },
        'NL': { // Pays-Bas
            250: 5.90, 500: 5.90, 750: 6.90, 1000: 6.90, 2000: 8.50,
            4000: 10.00, 5000: 19.50, 7000: 19.50, 10000: 19.50
        },
        'DE': { // Allemagne
            250: 6.50, 500: 6.50, 750: 7.50, 1000: 7.50, 2000: 9.00,
            4000: 10.50, 5000: 22.00, 7000: 22.00, 10000: 22.00
        },
        'LU': { // Luxembourg
            250: 5.00, 500: 5.00, 750: 6.00, 1000: 6.00, 2000: 7.50,
            4000: 8.50, 5000: 17.00, 7000: 17.00, 10000: 17.00
        },
        'CH': { // Suisse
            250: 6.50, 500: 7.00, 750: 7.50, 1000: 8.00, 2000: 10.00,
            4000: 12.00, 5000: 15.00, 7000: 18.00, 10000: 22.00
        }
    };

    const countryRates = rates[countryCode];
    if (!countryRates) return 0; // Country not supported

    if (weightInGrams <= 0) return 0;
    if (weightInGrams <= 250) return countryRates[250];
    if (weightInGrams <= 500) return countryRates[500];
    if (weightInGrams <= 750) return countryRates[750];
    if (weightInGrams <= 1000) return countryRates[1000];
    if (weightInGrams <= 2000) return countryRates[2000];
    if (weightInGrams <= 4000) return countryRates[4000];
    if (weightInGrams <= 5000) return countryRates[5000];
    if (weightInGrams <= 7000) return countryRates[7000];
    if (weightInGrams <= 10000) return countryRates[10000];
    return countryRates[10000]; // Fallback
};

/** Poids retenu par flacon pour le calcul des frais de port (flacon 100ml + étui + emballage). */
export const PERFUME_WEIGHT_G = 450;

/** Nombre d'articles pour déclencher la livraison gratuite */
export const FREE_SHIPPING_MIN_ITEMS = 3;

/** Livraison offerte en France dès 3 parfums ou dès ce montant de panier (TTC). */
export const FREE_SHIPPING_THRESHOLD = 100;

/**
 * Frais de port TTC facturés au client. Source unique utilisée par le panier,
 * Stripe et PayPal : le montant affiché est toujours le montant encaissé.
 * Règle commerciale :
 * - 1 parfum : 7,10 €
 * - 2 parfums : 9,59 €
 * - 3 parfums ou plus : GRATUIT (0,00 €)
 */
export const computeShippingCost = (
    method: 'colissimo' | 'mondial-relay',
    countryCode: string,
    totalQuantity: number,
    subtotal: number
): number => {
    if (totalQuantity <= 0) return 0;
    const country = (countryCode || 'FR').toUpperCase();
    if (country === 'FR' && (totalQuantity >= FREE_SHIPPING_MIN_ITEMS || subtotal >= FREE_SHIPPING_THRESHOLD)) {
        return 0;
    }
    if (totalQuantity === 1) return 7.10;
    if (totalQuantity === 2) return 9.59;
    const weight = totalQuantity * PERFUME_WEIGHT_G;
    return getColissimoCost(weight);
};


