export const getProducts = (): Product[] => {
    return products.filter(p => p.type !== 'variable' && p.productType === 'perfume').map(p => {
        const familyLower = p.family.toLowerCase();
        const intensity = p.intensity || (['oriental', 'oud', 'ambré', 'boisé', 'cuir'].some(f => familyLower.includes(f)) ? 'Forte' : 'Moyenne');
        const longevity = p.longevity || (intensity === 'Forte' ? 'Longue durée' : 'Moyenne');
        const occasion = p.occasion || (intensity === 'Forte' ? ['Soirée', 'Rendez-vous'] : ['Tous les jours', 'Travail']);
        return {
            ...p,
            intensity,
            longevity,
            occasion
        };
    });
};

export const getProductBySlug = (slug: string): Product | undefined => {
    if (!slug) return undefined;
    const allProducts = getProducts();
    const cleanSlug = decodeURIComponent(slug).toLowerCase().trim();

    // 1. Recherche exacte
    const exact = allProducts.find(p => p.slug.toLowerCase() === cleanSlug || p.id === cleanSlug);
    if (exact) return exact;

    // 2. Recherche sans suffixes courants (ex: -100ml, -80ml, -eau-de-parfum)
    const strip = (s: string) => s.replace(/-100ml|-80ml|-50ml|-eau-de-parfum|-parfum/g, '');
    const strippedSlug = strip(cleanSlug);
    const strippedMatch = allProducts.find(p => strip(p.slug.toLowerCase()) === strippedSlug);
    if (strippedMatch) return strippedMatch;

    // 3. Recherche par inclusion (anciens liens tronques ou rallonges)
    if (strippedSlug.length >= 5) {
        const inclusionMatch = allProducts.find(p =>
            p.slug.toLowerCase().includes(strippedSlug) || strippedSlug.includes(p.slug.toLowerCase())
        );
        if (inclusionMatch) return inclusionMatch;
    }

    return undefined;
};

export const getRelatedProducts = (currentProduct: Product): Product[] => {
    return getProducts().filter(p =>
        p.id !== currentProduct.id &&
        (p.family === currentProduct.family || p.brand.name === currentProduct.brand.name)
    ).slice(0, 4);
};

export const getBrands = (): Brand[] => {
    const productBrands = getProducts().map(p => p.brand).filter(b => b); // filter out undefined brands
    const uniqueBrandIds = new Set<string>();
    return productBrands.filter(brand => {
        if (!uniqueBrandIds.has(brand.id)) {
            uniqueBrandIds.add(brand.id);
            return true;
        }
        return false;
    });
};

