export const getNewArrivals = (): Product[] => {
    return getProducts().filter(p => p.isNew).sort((a, b) => parseInt(b.id) - parseInt(a.id));
};

export const getBestsellers = (): Product[] => {
    return getProducts().filter(p => p.isBestseller);
};


